node -v && node --input-type=module -e '
import assert from "node:assert/strict";
import { createPushGate } from "./bot.mjs";
const u = { id: "u_8841", timeZone: "Asia/Tokyo", quietStart: "22:00", quietEnd: "07:00", dailyCap: 3 };
const d = (s) => new Date(s);
let g = createPushGate();
// Tokyo 12:00 = 03:00Z
assert.deepEqual(g.attempt(u, d("2026-10-23T03:00:00Z")), { allowed: true, reason: null });
// quiet edges: 22:00 JST=13:00Z blocked, 21:59 allowed, 07:00 JST=22:00Z(prev) allowed, 06:59 blocked
g = createPushGate();
assert.equal(g.attempt(u, d("2026-10-23T13:00:00Z")).reason, "quiet_hours");
assert.equal(g.attempt(u, d("2026-10-23T12:59:00Z")).allowed, true);
assert.equal(g.attempt(u, d("2026-10-23T21:59:00Z")).reason, "quiet_hours");
assert.equal(g.attempt(u, d("2026-10-23T22:00:00Z")).allowed, true);
// cap: 3 allowed, 4th blocked, quiet-blocked calls do not count; next local day resets
g = createPushGate();
for (let i = 0; i < 3; i++) assert.equal(g.attempt(u, d(`2026-10-23T0${i}:00:00Z`)).allowed, true);
assert.equal(g.attempt(u, d("2026-10-23T05:00:00Z")).reason, "daily_cap_reached");
// 14:59Z = 23:59 JST quiet; 15:00Z = 00:00 JST Oct 24 quiet; 22:00Z = 07:00 JST Oct 24 new day
assert.equal(g.attempt(u, d("2026-10-23T22:00:00Z")).allowed, true);
// per-user independence and per-gate independence
assert.equal(g.attempt({ ...u, id: "x" }, d("2026-10-23T05:00:00Z")).allowed, true);
assert.equal(createPushGate().attempt(u, d("2026-10-23T05:00:00Z")).allowed, true);
// local day, not UTC: LA user, 23:30 PDT Oct 22 (06:30Z Oct 23) vs 00:30 PDT Oct 23 -> no quiet window
const la = { id: "la", timeZone: "America/Los_Angeles", quietStart: "00:00", quietEnd: "00:00", dailyCap: 1 };
g = createPushGate();
assert.equal(g.attempt(la, d("2026-10-23T06:30:00Z")).allowed, true);
assert.equal(g.attempt(la, d("2026-10-23T07:30:00Z")).reason, "daily_cap_reached"); // 00:30 PDT? no: 07:30Z=00:30 Oct23
' 2>&1 | tail -5

